package cn.mop.worker.backup;
import cn.mop.domain.DomainException;
import cn.mop.domain.backup.BackupArchivePayload.Scope;
import cn.mop.persistence.PostgresBackupRunRepository.LeaseClaim;
import cn.mop.persistence.PostgresBackupVersionRepository.*;
import java.time.Instant;import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static cn.mop.worker.backup.BackupVersionRegistrationDispatch.*;
class BackupVersionRegistrationDispatchTest {
 static UUID id(int n){return UUID.fromString("75000000-0000-4000-8000-"+String.format("%012d",n));}
 final Access access=new Access(id(1),id(2),7);final Scope scope=new Scope(id(1),id(3),id(4),1,id(5));
 final LeaseClaim lease=new LeaseClaim(id(6),"synthetic-owner",8);
 final Command command=new Command(access,scope,id(7),1,2,lease,"sha256:"+"a".repeat(64),"sha256:"+"b".repeat(64),"synthetic-trace");
 final Binding binding=new Binding(true,"backup-version-dispatch:synthetic-only");final Instant at=Instant.parse("2026-10-22T00:00:00Z");
 final List<Step> checks=new ArrayList<>();final List<String> calls=new ArrayList<>();final List<Command> commands=new ArrayList<>();Step denied;Registry registry;
 Receipt stored;boolean failRead,failWrite,commitThenFail,replay,malformed;int registrations;
 Candidate candidate(){return new Candidate(scope,1,2,"c".repeat(64),300,"kms-key-ref:synthetic","sha256:"+"d".repeat(64),at,lease);}
 Registration row(Candidate c){return new Registration(c,command.commandId(),"e".repeat(64),command.objectRecheckReference(),command.executionReference(),access.actorId(),at.plusMillis(1),2);}
 @BeforeEach void init(){registry=new Registry(){public Optional<Receipt> current(Access a,Scope s){calls.add("read");assertEquals(access,a);assertEquals(scope,s);if(failRead)throw new RuntimeException("private database secret");return Optional.ofNullable(stored);}public Receipt register(Command c){calls.add("register");commands.add(c);if(failWrite)throw new RuntimeException("private write failure");registrations++;stored=new Receipt(row(candidate()),false);if(commitThenFail)throw new RuntimeException("lost committed reply");return malformed?new Receipt(null,false):new Receipt(stored.registration(),replay);}};}
 BackupVersionRegistrationDispatch consumer(){return consumer(binding,registry);}
 BackupVersionRegistrationDispatch consumer(Binding b,Registry r){return new BackupVersionRegistrationDispatch(b,(binding,a,s,step)->{checks.add(step);assertEquals(access,a);assertEquals(scope,s);if(step==denied)throw new DomainException(403,"SYNTHETIC_DENIED","synthetic");},r);}
 @Test void disabledDoesNoReadAuthorizationOrRegistration(){var result=consumer(new Binding(false,null),registry).once(command);assertEquals(Status.DISABLED,result.status());assertFalse(result.registrationAndRunCompletionRecorded());assertTrue(calls.isEmpty());assertTrue(checks.isEmpty());}
 @Test void missingOriginalUsesExactlyOnePinnedRegistration(){var result=consumer().once(command);assertEquals(Status.REGISTRATION_AND_RUN_COMPLETION_RECORDED,result.status());assertEquals(2L,result.completedRunVersion());assertTrue(result.originalRegistrationMethodInvoked());assertFalse(result.historicalReceipt());assertEquals(List.of("read","register"),calls);assertEquals(List.of(Step.READ_ORIGINAL,Step.REGISTER_ORIGINAL,Step.RETURN_RESULT),checks);assertSame(command,commands.get(0));}
 @Test void matchingExistingRegistrationIsReadOnlyHistoricalEvidence(){stored=new Receipt(row(candidate()),false);var result=consumer().once(command);assertTrue(result.registrationAndRunCompletionRecorded());assertTrue(result.historicalReceipt());assertFalse(result.originalRegistrationMethodInvoked());assertEquals(List.of("read"),calls);assertEquals(0,registrations);}
 @Test void registrationNeverClaimsCurrentHealthDeviceRetentionOrRecovery(){var r=consumer().once(command);assertFalse(r.currentObjectHealthVerified());assertFalse(r.deviceExecutionAuthorized());assertFalse(r.retentionVerified());assertFalse(r.recoveryVerified());}
 @Test void lostCommitReplyReturnsUnknownThenNewInstanceOnlyReadsOriginal(){commitThenFail=true;assertEquals(Status.RECONCILIATION_REQUIRED,consumer().once(command).status());commitThenFail=false;var recovered=consumer().once(command);assertTrue(recovered.historicalReceipt());assertFalse(recovered.originalRegistrationMethodInvoked());assertEquals(1,registrations);assertEquals(List.of("read","register","read"),calls);}
 @Test void failedUncommittedAttemptCanOnlyRetrySameOriginalCommand(){failWrite=true;assertEquals(Status.RECONCILIATION_REQUIRED,consumer().once(command).status());assertNull(stored);failWrite=false;assertTrue(consumer().once(command).registrationAndRunCompletionRecorded());assertEquals(2,commands.size());assertSame(commands.get(0),commands.get(1));}
 @Test void malformedWriteReplyDoesNotClaimSuccessOrAutomaticallyRetry(){malformed=true;var r=consumer().once(command);assertEquals(Status.RECONCILIATION_REQUIRED,r.status());assertNull(r.completedRunVersion());assertFalse(r.registrationAndRunCompletionRecorded());assertEquals(1,commands.size());assertTrue(consumer().once(command).historicalReceipt());assertEquals(1,registrations);}
 @Test void sameCommandRacingReplayIsRetainedWithoutAnotherMutation(){replay=true;var r=consumer().once(command);assertTrue(r.historicalReceipt());assertTrue(r.originalRegistrationMethodInvoked());assertEquals(1,registrations);}
 @Test void readFailureIsSanitizedAndNeverTreatedAsMissing(){failRead=true;var error=assertThrows(DomainException.class,()->consumer().once(command));assertEquals(503,error.status);assertFalse(error.getMessage().contains("secret"));assertEquals(List.of("read"),calls);}
 @Test void denialBeforeReadMakesNoRepositoryCall(){denied=Step.READ_ORIGINAL;assertThrows(DomainException.class,()->consumer().once(command));assertTrue(calls.isEmpty());}
 @Test void denialBeforeRegistrationPreventsWrite(){denied=Step.REGISTER_ORIGINAL;assertThrows(DomainException.class,()->consumer().once(command));assertEquals(List.of("read"),calls);assertEquals(0,registrations);}
 @Test void revocationBeforeSuccessfulReturnSuppressesResultWithoutRollingBackEvidence(){denied=Step.RETURN_RESULT;assertThrows(DomainException.class,()->consumer().once(command));assertNotNull(stored);assertEquals(1,registrations);}
 @Test void revocationBeforeUnknownReturnSuppressesResult(){failWrite=true;denied=Step.RETURN_RESULT;assertThrows(DomainException.class,()->consumer().once(command));assertNull(stored);}
 @Test void malformedCurrentReceiptIsNotPermissionToAppend(){stored=new Receipt(null,false);assertThrows(DomainException.class,()->consumer().once(command));assertEquals(List.of("read"),calls);}
 @Test void historicalReplayCannotMasqueradeAsCurrentRead(){stored=new Receipt(row(candidate()),true);assertEquals(503,assertThrows(DomainException.class,()->consumer().once(command)).status);assertEquals(0,registrations);}
 @Test void commandBindingRequiresExplicitReferenceAndRejectsUrls(){assertThrows(DomainException.class,()->new Binding(true,null));assertThrows(DomainException.class,()->new Binding(true,"https://synthetic.invalid"));assertThrows(DomainException.class,()->new Binding(false,"raw-secret"));}
 @Test void commandRequiresMatchingTenantAndStableReferences(){assertThrows(DomainException.class,()->new Command(new Access(id(99),id(2),7),scope,id(7),1,2,lease,command.objectRecheckReference(),command.executionReference(),"trace"));assertThrows(DomainException.class,()->new Command(access,scope,id(7),0,2,lease,command.objectRecheckReference(),command.executionReference(),"trace"));assertThrows(DomainException.class,()->new Command(access,scope,id(7),1,2,lease,"https://synthetic.invalid",command.executionReference(),"trace"));}
 @Test void nullReadResultCannotAuthorizeRegistration(){Registry broken=new Registry(){public Optional<Receipt> current(Access a,Scope s){return null;}public Receipt register(Command c){fail("must not register");return null;}};assertEquals(503,assertThrows(DomainException.class,()->consumer(binding,broken).once(command)).status);}
 @Test void currentAuthorizationFailureKeeps403WithoutPrivateMessage(){Registry denied=new Registry(){public Optional<Receipt> current(Access a,Scope s){throw new DomainException(403,"PRIVATE","private credential");}public Receipt register(Command c){fail("must not register");return null;}};var error=assertThrows(DomainException.class,()->consumer(binding,denied).once(command));assertEquals(403,error.status);assertFalse(error.getMessage().contains("credential"));}
 @Test void differentOriginalFieldsAreRejectedBeforeRegister(){var original=row(candidate());for(int change=0;change<8;change++){var c=candidate();var changed=new Candidate(change==0?new Scope(id(1),id(99),id(4),1,id(5)):scope,change==1?2:1,change==2?3:2,c.encryptedSha256(),c.encryptedBytes(),c.keyReference(),c.archiveVerificationReference(),c.objectObservedAt(),change==3?new LeaseClaim(id(98),"synthetic-owner",8):lease);stored=new Receipt(new Registration(changed,change==4?id(99):original.commandId(),original.commandHash(),change==5?"sha256:"+"f".repeat(64):original.objectRecheckReference(),change==6?"sha256:"+"f".repeat(64):original.executionReference(),change==7?id(99):original.registeredBy(),original.registeredAt(),original.completedRunVersion()),false);assertEquals(409,assertThrows(DomainException.class,()->consumer().once(command)).status);}assertEquals(0,registrations);}
 @Test void invalidStoredVersionMetadataCannotBecomeSuccess(){for(int change=0;change<7;change++){var c=candidate();var changed=new Candidate(scope,1,2,change==0?"bad":c.encryptedSha256(),change==1?0:c.encryptedBytes(),change==2?"bad":c.keyReference(),change==3?"bad":c.archiveVerificationReference(),change==4?null:c.objectObservedAt(),lease);var original=row(changed);stored=new Receipt(new Registration(changed,original.commandId(),change==5?"bad":original.commandHash(),original.objectRecheckReference(),original.executionReference(),original.registeredBy(),change==6?at.minusMillis(1):original.registeredAt(),2),false);assertEquals(503,assertThrows(DomainException.class,()->consumer().once(command)).status);}assertEquals(0,registrations);}
}
